// The zsh integration: the script generated by the init subcommand.
package shell

import (
	"errors"
	"fmt"
	"strings"
)

// DefaultKey is the key combo bound by the shell integrations (ZshInit,
// BashInit, PowerShellInit) when --key is not given. Ctrl-O, not Ctrl-S:
// readline and ZLE use Ctrl-S for incremental forward search, and the
// terminal uses it for XOFF flow control.
const DefaultKey = "ctrl-o"

// ZshInit returns the zsh integration script, the output of `<prog> init
// zsh`: a script meant to be evaluated by an interactive zsh,
//
//	eval "$(wtr init zsh --key ctrl-o)"
//
// which binds key to a zle widget opening the inline picker of bin right
// below the prompt. The widget implements the flow described in Run: it
// captures stdout, the picker renders on the terminal and reports its result
// as a mode line ("run" or "insert") followed by the command line, and the
// widget then runs it (enter) or inserts it in the prompt (tab).
//
// prog is the name the binary was invoked as; it appears in the script's
// comments. bin is the command the widget launches — the invoked name,
// resolved through PATH at press time, or an absolute path. key is a combo
// name ("ctrl-o", "alt-x") or a raw zsh key sequence as bindkey takes it
// ("^[[15~" for F5).
func ZshInit(prog, bin, key string) (string, error) {
	if bin == "" {
		return "", errors.New("empty binary path")
	}
	if prog == "" {
		prog = "wtr"
	}
	seq, name, err := parseBindKey(key)
	if err != nil {
		return "", err
	}

	var b strings.Builder
	fmt.Fprintf(&b, `# %s: zsh integration, %s opens the inline picker.
#
# Evaluate it in an interactive shell:
#
#   eval "$(%s init zsh --key %s)"
#
# WTR_BIN overrides the binary the widget launches, WTR_FLAGS passes it extra
# flags, e.g. WTR_FLAGS=--debug-area to see the border of the managed area.

typeset -g WTR_BIN="${WTR_BIN:-%s}"
typeset -g WTR_FLAGS="${WTR_FLAGS:-}"
`, prog, name, prog, name, bin)

	ixon := disablesIXON(seq)
	if ixon {
		b.WriteString(`
# The terminal reads the bound key as flow control (Ctrl-S is XOFF, Ctrl-Q is
# XON) and would swallow it instead of delivering it to zle. Turn IXON off for
# this session; 'stty ixon' restores the default.

stty -ixon 2>/dev/null
`)
	}

	b.WriteString(`
_wtr_widget() {
  zle -I
  # zle runs commands with stdin not connected to the terminal; use /dev/tty
  # explicitly (same as television's shell integration). stdout is captured:
  # the picker renders on the terminal and prints its result here — a mode
  # line ("run" or "insert") followed by the command line.
  # The line is quoted for posix because zsh is the shell that will read it
  # back; it comes before WTR_FLAGS so a user can override it.
  local out
  out=$("$WTR_BIN" --inline --shell posix ${=WTR_FLAGS} < /dev/tty)

  local -a lines
  lines=("${(@f)out}")
  if (( ${#lines} >= 2 )); then
    case ${lines[1]} in
      run)
        BUFFER=${lines[2]}
        zle accept-line
        return
        ;;
      insert)
        LBUFFER+=${lines[2]}
        ;;
    esac
  fi
  zle reset-prompt
}

zle -N wtr-widget _wtr_widget
`)

	fmt.Fprintf(&b, "bindkey '%s' wtr-widget\n", seq)

	return b.String(), nil
}

// parseBindKey turns a --key value into the sequence bindkey expects and a
// human-readable name for the script's header comment: "ctrl-o" and "alt-x"
// are translated ("^O", "^[x"); anything starting with a caret is a raw zsh
// key sequence and is passed through unchanged.
func parseBindKey(spec string) (seq, name string, err error) {
	key := strings.TrimSpace(spec)
	if key == "" {
		return "", "", errors.New("empty key: use a combo name like ctrl-o or a raw sequence like ^[x")
	}
	if strings.HasPrefix(key, "^") {
		if len(key) < 2 {
			return "", "", fmt.Errorf("invalid key %q: a caret must introduce a key sequence", spec)
		}
		return key, key, nil
	}
	if rest, ok := cutPrefixFold(key, "ctrl-"); ok {
		if len(rest) != 1 || !isASCIILetter(rest[0]) {
			return "", "", fmt.Errorf("invalid key %q: ctrl- takes one letter, e.g. ctrl-o", spec)
		}
		upper := strings.ToUpper(rest)
		return "^" + upper, "Ctrl-" + upper, nil
	}
	if rest, ok := cutPrefixFold(key, "alt-"); ok {
		if len(rest) != 1 || rest[0] < 0x21 || rest[0] > 0x7e {
			return "", "", fmt.Errorf("invalid key %q: alt- takes one printable character, e.g. alt-x", spec)
		}
		return "^[" + rest, "Alt-" + rest, nil
	}
	return "", "", fmt.Errorf("invalid key %q: use a combo name like ctrl-o or alt-x, or a raw sequence like ^[x", spec)
}

// cutPrefixFold is strings.CutPrefix with a case-insensitive prefix.
func cutPrefixFold(s, prefix string) (string, bool) {
	if len(s) < len(prefix) || !strings.EqualFold(s[:len(prefix)], prefix) {
		return s, false
	}
	return s[len(prefix):], true
}

func isASCIILetter(c byte) bool {
	return 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z'
}

// disablesIXON reports whether binding seq needs IXON turned off: Ctrl-S is
// XOFF and Ctrl-Q is XON, so the terminal would swallow the key instead of
// delivering it to zle.
func disablesIXON(seq string) bool {
	return strings.EqualFold(seq, "^S") || strings.EqualFold(seq, "^Q")
}
